TAGS = ["bitcoin", "mempool", "rbf", "bip125", "pinning", "fee-market", "policy", "formal-verification", "mathlib"]

DEFINITION = {
    "definition_name": "BitcoinReplacement",
    "definition_title": "The fee rules of transaction replacement over an abstract mempool",
    "natural_language_statement": r"""An abstract mempool: no scripts, inputs or topology, only fees and sizes.

**`Tx`** — a (modified) fee in satoshi and a positive virtual size. **`FeeRate`** — Core's `FeePerVSize`: `fee` satoshi per `size` vbytes with `size > 0`; **`FeeRate.perKvB k`** is `CFeeRate(k)` $= k/1000$; **`DEFAULT_INCREMENTAL_RELAY_FEE`** $= 100$ (sat/kvB at this revision) and **`defaultIncrementalRelayFee`** its rate; **`MAX_REPLACEMENT_CANDIDATES`** $= 100$ (recorded, unused). **`FeeRate.getFee r v`** $= \lceil r.\text{fee} \cdot v / r.\text{size} \rceil$, computed as $(\text{fee} \cdot v + \text{size} - 1) / \text{size}$ in $\mathbb{N}$ (`CFeeRate::GetFee` = `FeePerVSize::EvaluateFeeUp`). **`Tx.feeRate`** is the exact fraction (fee, vsize); **`FeeRate.lt a b`** $\iff a.\text{fee} \cdot b.\text{size} < b.\text{fee} \cdot a.\text{size}$ and **`FeeRate.le`** likewise (`ByRatio`); **`Tx.feeRateQ`** $= \text{fee}/\text{vsize} \in \mathbb{Q}$.

**`Replacement`** — a new transaction, the multiset `evicted` of all entries it would remove (`all_conflicts`: direct conflicts and their descendants) and the sub-multiset `direct` of direct conflicts (`iters_conflicting`), with `direct ≤ evicted`. **`totalFee`, `totalVsize`** sum over a multiset.

**`PaysMoreThanConflicts R`** — every direct conflict's fee rate is strictly below the replacement's (`FeeRate.lt`), BIP125 rule 3 as implemented up to v29. **`PaysForRBF rate R`** — `totalFee evicted ≤ new.fee` and `rate.getFee new.vsize ≤ new.fee - totalFee evicted` (Core's `PaysForRBF`: at least the evicted fees, plus the incremental relay fee for the replacement's size). **`Valid rate R`** — both. **`IsChain rate t₀ [R₁, …, Rₙ]`** — each $R_i$ valid, $R_1$ evicts $t_0$, $R_{i+1}$ evicts $R_i$'s new transaction; **`chainEnd t₀ Rs`** is the last new transaction ($t_0$ for the empty chain); **`chainVsizes Rs`** the list of the new transactions' sizes.

**Formalization Note.** Imports Mathlib. `PaysForRBF` is transcribed from revision `a773e1e`; `PaysMoreThanConflicts` is absent there (replaced by the cluster-mempool feerate-diagram check, out of scope) and is transcribed from its last form (v29.0) with the exact `ByRatio` comparison of `a773e1e`. Fees are modified fees; structural rules, opt-in signalling, package relay and TRUC are not modelled; the eviction multiset is given, not computed from the mempool graph. The `getFee` of a zero-size or negative rate is not modelled.""",
}

THEOREMS = {
"BitcoinReplacement.paysForRBF_iff": dict(title="PaysForRBF is one inequality", nl=r"""For any rate and replacement: `PaysForRBF rate R` iff `totalFee R.evicted + rate.getFee R.new.vsize ≤ R.new.fee`.""", ms=None),
"BitcoinReplacement.fee_strictly_increases": dict(title="Every evicted transaction paid strictly less than its replacement", nl=r"""For a rate with positive numerator, a valid replacement $R$ and any $t \in$ `R.evicted`: `t.fee < R.new.fee`. With a zero incremental relay fee the inequality can be an equality, hence the hypothesis.""", ms=None),
"BitcoinReplacement.bandwidth_paid": dict(title="No free relay: a chain of replacements pays the incremental fee for every byte it relayed", nl=r"""For any rate, any $t_0$ and any chain `IsChain rate t₀ Rs` of $n$ replacements with new transactions $t_1, \dots, t_n$: $t_0.\text{fee} + \sum_{i=1}^{n} \text{getFee}(\text{vsize } t_i) \le t_n.\text{fee}$. The final transaction's fee covers the original fee plus the incremental relay fee of every replacement relayed along the way, in Core's own rounded-up `GetFee`.""", ms=None),
"BitcoinReplacement.bandwidth_paid_total": dict(title="No free relay, total-size form", nl=r"""Under the same hypotheses: $t_0.\text{fee} + \text{getFee}\left(\sum_i \text{vsize } t_i\right) \le t_n.\text{fee}$ (the ceiling is subadditive).""", ms=None),
"BitcoinReplacement.bandwidth_paid_rate": dict(title="No free relay, exact integer form", nl=r"""Under the same hypotheses: $t_0.\text{fee} \cdot \text{size} + \text{fee} \cdot \sum_i \text{vsize } t_i \le t_n.\text{fee} \cdot \text{size}$, where the rate is fee/size; no rounding is lost because `getFee` rounds up.""", ms=None),
"BitcoinReplacement.bandwidth_paid_real": dict(title="No free relay, rational form", nl=r"""Under the same hypotheses, in $\mathbb{Q}$: $t_0.\text{fee} + \frac{\text{fee}}{\text{size}} \sum_i \text{vsize } t_i \le t_n.\text{fee}$.""", ms=("The exact rate bound", "`bandwidth_paid` and the round-up `getFee r v ≥ fee·v/size`, summed over the chain.")),
"BitcoinReplacement.replacement_count_bound_min_vsize": dict(title="The number of replacements is bounded by the fee gained, per minimum size", nl=r"""For a chain of $n$ replacements each of virtual size at least $m$: $t_0.\text{fee} + n \cdot \text{getFee}(m) \le t_n.\text{fee}$.""", ms=None),
"BitcoinReplacement.replacement_count_bound": dict(title="The number of replacements is bounded by the fee gained", nl=r"""For a chain of $n$ replacements: $t_0.\text{fee} + n \cdot \text{getFee}(1) \le t_n.\text{fee}$.""", ms=None),
"BitcoinReplacement.replacement_count_le_fee": dict(title="Each replacement costs at least one satoshi", nl=r"""For a rate with positive numerator and a chain of $n$ replacements: $t_0.\text{fee} + n \le t_n.\text{fee}$.""", ms=None),
"BitcoinReplacement.replacement_count_bound_rate": dict(title="Replacements per satoshi: n ≤ (fee gained)/rate", nl=r"""For a chain of $n$ replacements: $n \cdot \text{fee} \le (t_n.\text{fee} - t_0.\text{fee}) \cdot \text{size}$, i.e. $n \le (t_n.\text{fee} - t_0.\text{fee}) / r$ with $r$ the rate in sat/vB.""", ms=("Linear in the fee", "`replacement_count_bound` with `getFee 1 · size ≥ fee`; an attacker who re-broadcasts $n$ times pays at least $n r$ satoshi above the original fee.")),
"BitcoinReplacement.pinning_cost": dict(title="Pinning: descendants attached to a transaction raise the cost of replacing it by their total fee", nl=r"""For a valid replacement $R$, a transaction $t$ and a multiset $D$ with $t ::ₘ D \le$ `R.evicted`: $t.\text{fee} + \text{totalFee}(D) + \text{getFee}(\text{vsize } R.\text{new}) \le R.\text{new}.\text{fee}$. Whoever attaches descendants of total fee $F$ to $t$ forces any replacement of $t$ to pay at least $F$ more.""", ms=None),
"BitcoinReplacement.pinning_cost_tight": dict(title="The pinning bound is exactly rule 4", nl=r"""If `R.evicted = t ::ₘ D` then `PaysForRBF rate R` iff $t.\text{fee} + \text{totalFee}(D) + \text{getFee}(\text{vsize } R.\text{new}) \le R.\text{new}.\text{fee}$: the bound of `pinning_cost` is attained, so the pinning cost is neither more nor less than the descendants' fees plus the incremental fee.""", ms=None),
"BitcoinReplacement.feeRateQ_lt_iff": dict(title="The ByRatio comparison is the comparison of exact fractions", nl=r"""For transactions $a, b$: $a.\text{fee}/a.\text{vsize} < b.\text{fee}/b.\text{vsize}$ in $\mathbb{Q}$ iff `FeeRate.lt a.feeRate b.feeRate`.""", ms=None),
"BitcoinReplacement.evicted_feerate_dominated": dict(title="Every direct conflict has a strictly lower fee rate than the replacement", nl=r"""For a valid replacement $R$ and $t \in$ `R.direct`: $t.\text{fee} \cdot \text{vsize}(R.\text{new}) < R.\text{new}.\text{fee} \cdot \text{vsize}(t)$. Rule 3, in cross-multiplied form.""", ms=None),
"BitcoinReplacement.min_direct_feerate_lt": dict(title="The lowest-feerate direct conflict is below the replacement", nl=r"""For a valid replacement with at least one direct conflict there is a direct conflict $t$ whose exact fee rate is $\le$ every other direct conflict's and $<$ the replacement's.""", ms=None),
}
